insert into auth.users(id,email,email_confirmed_at) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'corner'||n||'@example.test',now() from generate_series(50,54)n;
insert into public.profiles(user_id,full_name) select id,'Corner user '||right(id::text,2) from auth.users where email like 'corner%@example.test';
insert into public.organizations(id,name) values('10000000-0000-0000-0000-000000000050','Corner A'),('10000000-0000-0000-0000-000000000051','Corner B');
insert into public.organization_memberships(id,organization_id,user_id,email,role)
select ('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,case when n<53 then '10000000-0000-0000-0000-000000000050' else '10000000-0000-0000-0000-000000000051' end::uuid,('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'corner'||n||'@example.test',case when n in(50,53) then 'manager' else 'employee' end from generate_series(50,54)n;
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000051';
select test.ok(public.get_team_corner('10000000-0000-0000-0000-000000000050')->>'can_post'='true','employee can open own store feed');
select test.rejects($q$select public.get_team_corner('10000000-0000-0000-0000-000000000051')$q$,'Store feed access required','employee cannot open another store feed');
