-- Stable cursor paging, including rows with identical timestamps.
select public.create_team_corner_post('10000000-0000-0000-0000-000000000050','90000000-0000-4000-8000-000000000050','Pinned store announcement',pin=>true);
reset role;
insert into public.team_corner_posts(id,organization_id,author_id,author_name,body,created_at)
select ('92000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'10000000-0000-0000-0000-000000000050','00000000-0000-0000-0000-000000000050','Manager','History '||n,'2026-01-01'::timestamptz from generate_series(1,25)n;
insert into public.team_corner_comments(id,post_id,organization_id,author_id,author_name,body,created_at)
select ('93000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'90000000-0000-4000-8000-000000000050','10000000-0000-0000-0000-000000000050','00000000-0000-0000-0000-000000000052','Employee','Comment '||n,'2026-01-01'::timestamptz from generate_series(1,25)n;
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000052';
insert into test.codes select 'corner-page',public.get_team_corner('10000000-0000-0000-0000-000000000050')::text;
select test.ok((select jsonb_array_length(code::jsonb->'posts')=20 and (code::jsonb->>'has_more')::boolean and jsonb_array_length(code::jsonb->'pinned')=1 from test.codes where label='corner-page'),'feed pages twenty posts with pinned announcements separate');
select test.ok(jsonb_array_length(public.get_team_corner('10000000-0000-0000-0000-000000000050','2026-01-01',(select (code::jsonb->'posts'->-1->>'id')::uuid from test.codes where label='corner-page'))->'posts')=5,'post cursor handles equal timestamps without duplicates');
insert into test.codes select 'corner-comments-page',public.get_team_corner_comments('90000000-0000-4000-8000-000000000050')::text;
select test.ok((select jsonb_array_length(code::jsonb->'comments')=20 and (code::jsonb->>'has_more')::boolean from test.codes where label='corner-comments-page'),'comments are paged without losing older discussion');
select test.ok(jsonb_array_length(public.get_team_corner_comments('90000000-0000-4000-8000-000000000050','2026-01-01',(select (code::jsonb->'comments'->0->>'id')::uuid from test.codes where label='corner-comments-page'))->'comments')=5,'comment cursor handles equal timestamps');
reset role;
select test.ok(not has_function_privilege('anon','public.get_team_corner(uuid,timestamptz,uuid)','execute'),'anonymous feed reads denied');
select test.ok(not has_table_privilege('authenticated','private.team_corner_support','select'),'support audit records are private');
select 'Passed Team Corner security, photos, moderation, support, and paging ('||count(*)||' total SQL assertions).' from test.results;
